<?php
/** Free/Core customer support and basic service history. */
function veyra_user_tickets(int $uid,int $limit=50): array {$q=db()->prepare('SELECT * FROM support_tickets WHERE user_id=? ORDER BY last_message_at DESC LIMIT '.max(1,min(100,$limit)));$q->execute([$uid]);return$q->fetchAll()?:[];}
function veyra_ticket_messages(int $ticketId): array {$q=db()->prepare('SELECT * FROM support_messages WHERE ticket_id=? ORDER BY id');$q->execute([$ticketId]);return$q->fetchAll()?:[];}
function veyra_create_ticket(int $uid,array $in): array {$sub=trim((string)($in['subject']??''));$body=trim((string)($in['message']??''));if($sub===''||$body==='')throw new RuntimeException('TICKET_SUBJECT_MESSAGE_REQUIRED');$sid=max(0,(int)($in['service_id']??0));if($sid&&!veyra_service_record($sid,$uid))throw new RuntimeException('SERVICE_NOT_FOUND');db()->prepare('INSERT INTO support_tickets (user_id,user_service_id,order_id,category,priority,status,subject) VALUES (?,?,?,?,?,"open",?)')->execute([$uid,$sid?:null,max(0,(int)($in['order_id']??0))?:null,substr((string)($in['category']??'other'),0,64),substr((string)($in['priority']??'normal'),0,16),mb_substr($sub,0,255)]);$id=(int)db()->lastInsertId();db()->prepare('INSERT INTO support_messages (ticket_id,sender_type,sender_id,body) VALUES (?,"user",?,?)')->execute([$id,$uid,$body]);return ['ticket_id'=>$id];}
function veyra_reply_ticket(int $ticketId,string $senderType,int $senderId,string $body): void {$body=trim($body);if($body==='')throw new RuntimeException('EMPTY_MESSAGE');db()->prepare('INSERT INTO support_messages (ticket_id,sender_type,sender_id,body) VALUES (?,?,?,?)')->execute([$ticketId,$senderType,$senderId,$body]);$status=$senderType==='admin'?'waiting_customer':'waiting_admin';db()->prepare('UPDATE support_tickets SET status=?,last_message_at=NOW() WHERE id=?')->execute([$status,$ticketId]);}
function veyra_service_usage_history(int $serviceId,int $userId=0,int $days=30): array {if($userId&&!veyra_service_record($serviceId,$userId))throw new RuntimeException('SERVICE_NOT_FOUND');$days=max(1,min(365,$days));$q=db()->prepare('SELECT created_at,SUM(traffic_used_bytes) traffic_used_bytes,SUM(COALESCE(traffic_limit_bytes,0)) traffic_limit_bytes,MIN(expires_at) expires_at FROM service_usage_snapshots WHERE user_service_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL '.$days.' DAY) GROUP BY DATE_FORMAT(created_at,"%Y-%m-%d %H:00:00") ORDER BY created_at');$q->execute([$serviceId]);return$q->fetchAll()?:[];}
function veyra_service_event_history(int $serviceId,int $userId=0,int $limit=100): array {if($userId&&!veyra_service_record($serviceId,$userId))throw new RuntimeException('SERVICE_NOT_FOUND');$q=db()->prepare('SELECT * FROM service_events WHERE user_service_id=? ORDER BY id DESC LIMIT '.max(1,min(300,$limit)));$q->execute([$serviceId]);return$q->fetchAll()?:[];}
